def fuzzy_match(pattern: str, text: str) -> tuple[bool, list[int]]:
    if not pattern:
        return True, []

    pattern = pattern.lower()
    text_lower = text.lower()

    pattern_idx = 0
    indices = []

    for i, char in enumerate(text_lower):
        if pattern_idx < len(pattern) and char == pattern[pattern_idx]:
            indices.append(i)
            pattern_idx += 1

